"""Small standard-library JSON Schema subset for config validation."""
import json
import math
import re


def _matches_type(value, expected):
    choices = expected if isinstance(expected, list) else [expected]
    def one(kind):
        if kind == 'null': return value is None
        if kind == 'boolean': return isinstance(value, bool)
        if kind == 'object': return isinstance(value, dict)
        if kind == 'array': return isinstance(value, list)
        if kind == 'string': return isinstance(value, str)
        if kind == 'integer': return isinstance(value, int) and not isinstance(value, bool)
        if kind == 'number': return isinstance(value, (int, float)) and not isinstance(value, bool)
        return True
    return any(one(x) for x in choices)


def _validate(value, schema, path='$'):
    if not isinstance(schema, dict): return []
    errs=[]
    if '$ref' in schema:
        return []  # external refs are intentionally unresolved here
    if 'type' in schema and not _matches_type(value, schema['type']):
        types = schema['type']
        label = ', '.join(types) if isinstance(types, list) else types
        return [f'{path}: expected {label}']
    if 'const' in schema and value != schema['const']:
        errs.append(f'{path}: must equal {schema["const"]!r}')
    if 'enum' in schema and value not in schema['enum']:
        errs.append(f'{path}: value is not one of the allowed values')
    if isinstance(value, dict):
        for key in schema.get('required', []):
            if key not in value: errs.append(f'{path}: missing required property {key!r}')
        props=schema.get('properties', {})
        for key, val in value.items():
            if key in props: errs.extend(_validate(val, props[key], f'{path}.{key}'))
            elif schema.get('additionalProperties') is False: errs.append(f'{path}: additional property {key!r} is not allowed')
            elif isinstance(schema.get('additionalProperties'), dict): errs.extend(_validate(val, schema['additionalProperties'], f'{path}.{key}'))
        if 'minProperties' in schema and len(value)<schema['minProperties']: errs.append(f'{path}: must have at least {schema["minProperties"]} properties')
        if 'maxProperties' in schema and len(value)>schema['maxProperties']: errs.append(f'{path}: must have at most {schema["maxProperties"]} properties')
    if isinstance(value, list):
        if 'items' in schema:
            for i, val in enumerate(value): errs.extend(_validate(val, schema['items'], f'{path}[{i}]'))
        if 'minItems' in schema and len(value)<schema['minItems']: errs.append(f'{path}: must have at least {schema["minItems"]} items')
        if 'maxItems' in schema and len(value)>schema['maxItems']: errs.append(f'{path}: must have at most {schema["maxItems"]} items')
    if isinstance(value, str):
        if 'minLength' in schema and len(value)<schema['minLength']: errs.append(f'{path}: string is too short')
        if 'maxLength' in schema and len(value)>schema['maxLength']: errs.append(f'{path}: string is too long')
        if 'pattern' in schema and not re.search(schema['pattern'], value): errs.append(f'{path}: string does not match pattern {schema["pattern"]!r}')
        if 'format' in schema and schema['format']=='email' and not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', value): errs.append(f'{path}: string is not a valid email')
    if isinstance(value, (int,float)) and not isinstance(value,bool):
        if 'minimum' in schema and value<schema['minimum']: errs.append(f'{path}: must be >= {schema["minimum"]}')
        if 'maximum' in schema and value>schema['maximum']: errs.append(f'{path}: must be <= {schema["maximum"]}')
        if 'exclusiveMinimum' in schema and value<=schema['exclusiveMinimum']: errs.append(f'{path}: must be > {schema["exclusiveMinimum"]}')
        if 'exclusiveMaximum' in schema and value>=schema['exclusiveMaximum']: errs.append(f'{path}: must be < {schema["exclusiveMaximum"]}')
    if 'allOf' in schema:
        for sub in schema['allOf']: errs.extend(_validate(value,sub,path))
    if 'anyOf' in schema and not any(not _validate(value,s,path) for s in schema['anyOf']): errs.append(f'{path}: does not match any allowed schema')
    if 'oneOf' in schema and sum(not _validate(value,s,path) for s in schema['oneOf']) != 1: errs.append(f'{path}: does not match exactly one allowed schema')
    if 'not' in schema and not _validate(value,schema['not'],path): errs.append(f'{path}: matches a forbidden schema')
    return errs


def validate_json_schema(instance_text, schema_path):
    """Return a list of errors; empty when content conforms to schema."""
    try:
        instance=json.loads(instance_text)
        with open(schema_path, encoding='utf-8') as stream: schema=json.load(stream)
    except Exception as exc:
        return [str(exc)]
    return _validate(instance, schema)

