def _simple_toml(text):
    """Parse the ordinary scalar/array/table subset used by .cfv.toml."""
    result = {}
    current = result
    lines = iter(enumerate(text.splitlines(), 1))
    for n, raw in lines:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        m = re.fullmatch(r"\[([^\]]+)\]", line)
        if m:
            current = result
            for part in m.group(1).split("."):
                part = part.strip().strip('"\'')
                current = current.setdefault(part, {})
            continue
        if "=" not in line:
            raise ValueError(f"line {n}: expected key = value")
        key, value = (x.strip() for x in line.split("=", 1))
        key = key.strip('"\'')
        # Remove trailing comments outside a quoted string.
        quote = None
        for i, c in enumerate(value):
            if quote:
                if c == quote and (i == 0 or value[i - 1] != "\\"):
                    quote = None
            elif c in "\"'":
                quote = c
            elif c == "#":
                value = value[:i].rstrip()
                break
        if value.startswith('"""') or value.startswith("'''"):
            # Basic multiline string support.
            marker = value[:3]
            if value.endswith(marker) and len(value) > 6:
                val = value[3:-3]
            else:
                chunks = [value[3:]]
                while not chunks[-1].endswith(marker):
                    try:
                        _, more = next(lines)
                    except StopIteration:
                        raise ValueError(f"line {n}: unterminated multiline string")
                    chunks.append(more)
                val = "\n".join(chunks)[:-3]
        else:
            try:
                val = ast.literal_eval(value)
            except Exception:
                if value.lower() in ("true", "false"):
                    val = value.lower() == "true"
                elif re.fullmatch(r"[+-]?\d+", value):
                    val = int(value)
                elif re.fullmatch(r"[+-]?\d+\.\d+", value):
                    val = float(value)
                else:
                    raise ValueError(f"line {n}: invalid value")
        current[key] = val
    return result


def _parse(text):
    if tomllib:
        return tomllib.loads(text)
    return _simple_toml(text)


