        for element, body in re.findall(r'<!ATTLIST\s+([A-Za-z_:][\w:.-]*)\s+([^>]+)>',subset,re.S):
            if element != node.tag: continue
            parts=re.findall(r'\([^)]*\)|"[^"]*"|\S+',body)
