                if kind.startswith('(') and attr in node.attrib and node.attrib[attr] not in kind.strip('()').split('|'): return False
        return True
    def valid_element(node):
        name=node.tag
        model=declarations.get(name)
        if model is None: return False
        if not valid_attrs(node): return False
        child_names=[child.tag for child in list(node)]
        if any(child not in declarations for child in child_names): return False
